#!/usr/bin/env node
/**
 * Validates every theme against schema/theme.schema.json and generates:
 *   themes/<id>/README.md   page of the theme, with its preview
 *   index.json              list of the themes, read by Antares
 *   the theme table in README.md (between the THEMES markers)
 *
 *   node scripts/build.js           validate and write
 *   node scripts/build.js --check   validate and fail if a generated file is out of date (CI)
 */
const fs = require('fs');
const path = require('path');
const Ajv = require('ajv');

const root = path.resolve(__dirname, '..');
const check = process.argv.includes('--check');
const RAW = 'https://raw.githubusercontent.com/antares-sql/themes/main';

const schema = JSON.parse(fs.readFileSync(path.join(root, 'schema/theme.schema.json'), 'utf8'));
const validate = new Ajv({ allErrors: true, strict: false }).compile(schema);

const problems = [];
const outdated = [];

const write = (file, content) => {
   const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
   if (current === content) return;
   if (check) outdated.push(path.relative(root, file));
   else fs.writeFileSync(file, content);
};

const themesDir = path.join(root, 'themes');
const themes = [];
for (const dir of fs.readdirSync(themesDir).sort()) {
   const file = path.join(themesDir, dir, 'theme.json');
   if (!fs.existsSync(file)) continue;
   let theme;
   try {
      theme = JSON.parse(fs.readFileSync(file, 'utf8'));
   }
   catch (err) {
      problems.push(`${dir}/theme.json: invalid JSON (${err.message})`);
      continue;
   }
   if (!validate(theme)) {
      for (const err of validate.errors) problems.push(`${dir}/theme.json${err.instancePath}: ${err.message}`);
      continue;
   }
   if (theme.id !== dir) problems.push(`${dir}/theme.json: the id "${theme.id}" must match the folder name`);
   if (!fs.existsSync(path.join(themesDir, dir, 'preview.png'))) problems.push(`${dir}: preview.png is missing`);
   themes.push(theme);
}

const ids = new Set();
for (const theme of themes) {
   if (ids.has(theme.id)) problems.push(`duplicated id ${theme.id}`);
   ids.add(theme.id);
}

if (problems.length) {
   console.error(problems.map(p => `✖ ${p}`).join('\n'));
   process.exit(1);
}

const appearanceLabel = theme => theme.appearance === 'dark' ? '🌙 Dark' : '☀️ Light';

for (const theme of themes) {
   const readme = [
      `# ${theme.name}`,
      '',
      theme.description || '',
      '',
      `![${theme.name}](preview.png)`,
      '',
      '| | |',
      '|---|---|',
      `| Appearance | ${appearanceLabel(theme)} |`,
      theme.author ? `| Author | ${theme.author} |` : null,
      theme.version ? `| Version | ${theme.version} |` : null,
      theme.license ? `| License | ${theme.license} |` : null,
      theme.tags?.length ? `| Tags | ${theme.tags.map(tag => `\`${tag}\``).join(' ')} |` : null,
      '',
      '## Install',
      '',
      `Download [theme.json](${RAW}/themes/${theme.id}/theme.json), then in Antares open **Settings → Themes → Import from file**.`,
      '',
      '<!-- Generated by scripts/build.js from theme.json: edit theme.json, not this file -->',
      ''
   ].filter(line => line !== null).join('\n');
   write(path.join(themesDir, theme.id, 'README.md'), readme);
}

const index = {
   schemaVersion: 1,
   themes: themes.map(theme => ({
      id: theme.id,
      name: theme.name,
      appearance: theme.appearance,
      author: theme.author,
      description: theme.description,
      tags: theme.tags ?? [],
      // relative to index.json, so a fork or a local copy works too
      theme: `themes/${theme.id}/theme.json`,
      preview: `themes/${theme.id}/preview.png`
   }))
};
write(path.join(root, 'index.json'), JSON.stringify(index, null, 2) + '\n');

const readmePath = path.join(root, 'README.md');
const readme = fs.readFileSync(readmePath, 'utf8');
const rows = themes.map(theme => `| [${theme.name}](themes/${theme.id}) | ${appearanceLabel(theme)} | <img src="themes/${theme.id}/preview.png" width="240"> |`);
const table = ['<!-- THEMES:START -->', '| Theme | Appearance | Preview |', '|---|---|---|', ...rows, '<!-- THEMES:END -->'].join('\n');
write(readmePath, readme.replace(/<!-- THEMES:START -->[\s\S]*<!-- THEMES:END -->/, table));

if (outdated.length) {
   console.error(`✖ Generated files out of date, run "npm run build":\n  ${outdated.join('\n  ')}`);
   process.exit(1);
}
console.log(`✔ ${themes.length} themes`);
